  function drawBat(x,y,s=1){ctx.save();ctx.translate(x,y);ctx.scale(s,s);glow("#fb7185",10);ctx.fillStyle="#6b102d";ctx.beginPath();ctx.moveTo(0,3);ctx.quadraticCurveTo(-20,-16,-31,0);ctx.quadraticCurveTo(-20,-3,-12,14);ctx.quadraticCurveTo(0,21,12,14);ctx.quadraticCurveTo(20,-3,31,0);ctx.quadraticCurveTo(20,-16,0,3);ctx.fill();ctx.fillStyle="#fb7185";ctx.fillRect(-7,2,3,3);ctx.fillRect(4,2,3,3);noGlow();ctx.restore()}
  function drawGhost(x,y,s=1){ctx.save();ctx.translate(x,y);ctx.scale(s,s);glow("#a5f3fc");ctx.globalAlpha=.72;ctx.fillStyle="#cffafe";ctx.beginPath();ctx.arc(0,-8,17,Math.PI,0);ctx.lineTo(18,23);ctx.lineTo(8,16);ctx.lineTo(0,24);ctx.lineTo(-9,16);ctx.lineTo(-18,23);ctx.closePath();ctx.fill();ctx.globalAlpha=1;ctx.fillStyle="#0e3b55";ctx.beginPath();ctx.arc(-6,-8,3,0,7);ctx.arc(6,-8,3,0,7);ctx.fill();noGlow();ctx.restore()}
  function drawFrankenstein(x,y,s=1,throwPhase=-1){const tantrum=Math.sin(performance.now()/90),stomp=Math.abs(Math.sin(performance.now()/140))*5,throwing=throwPhase>=0,wind=throwing?Math.sin(Math.min(1,throwPhase)*Math.PI):0;ctx.save();ctx.translate(x,y-stomp);ctx.scale(s,s);glow("#4ade80",8);ctx.fillStyle="#65a30d";ctx.fillRect(-16,-21,32,38);ctx.fillStyle="#172016";ctx.fillRect(-18,-27,36,10);ctx.fillStyle="#d9ff63";ctx.fillRect(-10,-10,5,3);ctx.fillRect(5,-10,5,3);ctx.strokeStyle="#65a30d";ctx.lineWidth=9;ctx.lineCap="round";ctx.beginPath();ctx.moveTo(-15,-6);ctx.lineTo(throwing?-28-22*throwPhase:-29,throwing?-20-28*wind:-18-tantrum*12);ctx.moveTo(15,-6);ctx.lineTo(throwing?4-30*throwPhase:29,throwing?-28-22*wind:-18+tantrum*12);ctx.stroke();ctx.fillStyle="#94a3b8";ctx.fillRect(-22,-8,6,6);ctx.fillRect(16,-8,6,6);ctx.fillStyle="#292524";ctx.fillRect(-15,17,11,17+stomp);ctx.fillRect(4,17,11,22-stomp);noGlow();ctx.restore()}
  function drawAlien(x,y,s=1){ctx.save();ctx.translate(x,y);ctx.scale(s,s);glow("#4ade80",12);ctx.fillStyle="#86efac";ctx.beginPath();ctx.ellipse(0,0,18,25,0,0,7);ctx.fill();ctx.fillStyle="#07140b";ctx.beginPath();ctx.ellipse(-7,-4,5,9,-.3,0,7);ctx.ellipse(7,-4,5,9,.3,0,7);ctx.fill();noGlow();ctx.restore()}
